"use strict";
// The Brewboard entry points, all running the one workflow in SKILL.md. The main entry point, then one suggestion
// entry per subcommand named `bb <sub>`, generated by the build from SUBCOMMANDS: picking it types `/bb <sub> `, which
// the CLI sends to the main entry point (verified interactively; see scripts/build-dist.js):
//   Claude Code   /bb (arguments as $ARGUMENTS)     skill folder  "bb <sub>"
//   OpenCode      /bb (generated from Claude's)     command file  "bb <sub>.md"
//   Antigravity   the skill bb (= /bb)              skill named   "bb <sub>" (folder bb-<id>)
//   Codex         the skill $bb (same file)         skill named   "bb <sub>" (folder bb-<id>)
// Static checks of dist/ and the installer's text; agents-e2e.test.js asks the real CLIs what they discover.
const test = require("node:test");
const assert = require("node:assert");
const fs = require("fs");
const path = require("path");
const { spawn, spawnSync } = require("child_process");
const { tmpHome } = require("./helpers");
const { install } = require("../lib/install");
const { detectAgents, agentPaths } = require("../lib/agents");
const tracking = require("../lib/tracking");
const { SUBCOMMANDS: TABLE, codexId } = require("../scripts/build-dist");

const ROOT = path.join(__dirname, "..");
const DIST = path.join(ROOT, "dist");
const BIN = path.join(ROOT, "bin", "brewboard-skill.js");
const read = (rel) => fs.readFileSync(path.join(DIST, rel), "utf8");
const SUBCOMMANDS = ["init", "list_projects", "list_tasks", "list_tickets", "cycles", "log_time", "timesheets",
                     "create_mom", "moms", "show", "find", "status"];

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const full = path.join(dir, e.name);
    return e.isDirectory() ? walk(full) : [full];
  });
}

// The YAML frontmatter as {key: raw value}; fails on anything but `key: value` lines between two `---` lines.
function frontmatter(text, name) {
  const m = /^---\n([\s\S]*?)\n---\n/.exec(text);
  assert.ok(m, `${name}: starts with a --- frontmatter block`);
  return Object.fromEntries(m[1].split("\n").map((line) => {
    const kv = /^([a-z][a-z-]*): (.+)$/.exec(line);
    assert.ok(kv, `${name}: frontmatter line ${JSON.stringify(line)} is not \`key: value\``);
    return [kv[1], kv[2]];
  }));
}

// A double-quoted YAML scalar without escapes reads the same as a JSON string; anything unquoted with ": " would not
// parse in Antigravity (its changelog: "mapping values are not allowed in this context").
function quoted(value, name) {
  assert.match(value, /^"[^"\\]*"$/, `${name}: description is one double-quoted string with no inner quotes`);
  return JSON.parse(value);
}

test("no /bb-* or namespaced files; spaces only in the Claude Code and OpenCode entry names, exactly one each", () => {
  assert.deepStrictEqual(fs.readdirSync(path.join(DIST, "adapters", "claude-code")), ["bb.md"]);
  assert.deepStrictEqual(fs.readdirSync(path.join(DIST, "adapters", "opencode")).sort(),
                         ["bb.md", ...SUBCOMMANDS.map((x) => `bb ${x}.md`)].sort());
  for (const f of walk(path.join(DIST, "adapters"))) {
    const rel = path.relative(path.join(DIST, "adapters"), f).split(path.sep).join("/");
    assert.doesNotMatch(rel, /:|\t|\s{2}|^\s|\s\//, `${rel}: no colon, tab, double or edge space`);
    if (/\s/.test(rel)) assert.match(rel, /^(claude-skills\/bb [a-z_]+\/SKILL\.md|opencode\/bb [a-z_]+\.md)$/, rel);
    assert.doesNotMatch(path.basename(rel), /^bb-.*\.md$/, `${rel}: an old /bb-<subcommand> command file`);
  }
  for (const gone of ["claude-plugin", "antigravity-plugin", "opencode/bb"]) assert.ok(!fs.existsSync(path.join(DIST, "adapters", gone)), gone);
});

test("/bb forwards everything after it to the shared workflow", () => {
  for (const rel of ["adapters/claude-code/bb.md", "adapters/opencode/bb.md"]) {
    const text = read(rel);
    assert.strictEqual(text.split("$ARGUMENTS").length - 1, 1, `${rel}: $ARGUMENTS appears once`);
    assert.match(text, /^Subcommand and arguments: \$ARGUMENTS$/m, rel);
    assert.match(text, /Read ~\/\.bb\/skill\/SKILL\.md and follow it\./, rel);
  }
  const fm = frontmatter(read("adapters/claude-code/bb.md"), "claude-code/bb.md");
  quoted(fm.description.startsWith("\"") ? fm.description : `"${fm.description}"`, "claude-code/bb.md");
  const hint = JSON.parse(fm["argument-hint"]);
  for (const sub of SUBCOMMANDS) assert.ok(hint.includes(sub), `argument-hint names ${sub}`);
  const oc = frontmatter(read("adapters/opencode/bb.md"), "opencode/bb.md");
  assert.deepStrictEqual(Object.keys(oc), ["description"], "OpenCode gets no Claude-only frontmatter");
  assert.match(read("adapters/agent-skill/bb.md"), /The subcommand and its arguments are whatever the user wrote after \/bb \(`\$bb` in Codex\)/);
});

test("the shared skill bb has valid, quoted frontmatter", () => {
  const fm = frontmatter(read("adapters/agent-skill/bb.md"), "agent-skill/bb.md");
  assert.deepStrictEqual(Object.keys(fm), ["name", "description"]);
  assert.strictEqual(fm.name, "bb");
  assert.match(quoted(fm.description, "agent-skill/bb.md"), /\/bb/);
});

test("the subcommand table names exactly the twelve workflows, each documented in SKILL.md", () => {
  assert.deepStrictEqual(TABLE.map(([sub]) => sub), SUBCOMMANDS);
  const skill = read("skill/SKILL.md");
  for (const sub of SUBCOMMANDS) assert.ok(skill.includes(`\n### ${sub}\n`), `SKILL.md has a ${sub} section`);
});

// Every per-subcommand entry: thin, pointing at SKILL.md's workflow of that name, passing its arguments on.
function thin(text, sub, where) {
  assert.match(text, /Read ~\/\.bb\/skill\/SKILL\.md and follow it/, where);
  assert.ok(text.includes(sub), where);
  assert.doesNotMatch(text, /bb\.py (?!init)/, `${where}: no workflow of its own`);
  assert.ok(text.length < 1200, `${where}: stays a thin wrapper`);
}

test("Claude Code: one skill per subcommand, its folder named `bb <sub>` (what picking it types), user-only", () => {
  assert.deepStrictEqual(fs.readdirSync(path.join(DIST, "adapters", "claude-skills")).sort(), SUBCOMMANDS.map((x) => `bb ${x}`).sort());
  for (const [sub, what] of TABLE) {
    const rel = `adapters/claude-skills/bb ${sub}/SKILL.md`;
    assert.deepStrictEqual(fs.readdirSync(path.join(DIST, path.dirname(rel))), ["SKILL.md"]);
    const text = read(rel);
    const fm = frontmatter(text, rel);
    assert.deepStrictEqual(Object.keys(fm), ["description", "disable-model-invocation"], `${rel}: no name: the folder name is the command`);
    assert.strictEqual(quoted(fm.description, rel), `Brewboard - ${what}`);
    assert.strictEqual(fm["disable-model-invocation"], "true", `${rel}: only the user picks it; the model uses /bb`);
    assert.strictEqual(text.split("$ARGUMENTS").length - 1, 1, `${rel}: $ARGUMENTS appears once`);
    assert.match(text, new RegExp(`^Subcommand and arguments: ${sub} \\$ARGUMENTS$`, "m"), rel);
    thin(text, sub, rel);
  }
});

test("OpenCode: one command per subcommand, its file named `bb <sub>.md`, forwarding $ARGUMENTS", () => {
  for (const [sub, what] of TABLE) {
    const rel = `adapters/opencode/bb ${sub}.md`;
    const text = read(rel);
    const fm = frontmatter(text, rel);
    assert.deepStrictEqual(Object.keys(fm), ["description"], `${rel}: no Claude-only frontmatter`);
    assert.strictEqual(quoted(fm.description, rel), `Brewboard - ${what}`);
    assert.strictEqual(text.split("$ARGUMENTS").length - 1, 1, `${rel}: $ARGUMENTS appears once`);
    assert.match(text, new RegExp(`^Subcommand and arguments: ${sub} \\$ARGUMENTS$`, "m"), rel);
    thin(text, sub, rel);
  }
});

for (const [agent, dir, main] of [["Antigravity", "antigravity-skills", "/bb"], ["Codex", "codex", "$bb"]]) {
  test(`${agent}: one skill per subcommand named "bb <sub>" (shown as ${main} <sub>), in a folder named bb-<id>`, () => {
    assert.deepStrictEqual(fs.readdirSync(path.join(DIST, "adapters", dir)).sort(), SUBCOMMANDS.map(codexId).sort());
    for (const [sub, what] of TABLE) {
      const id = codexId(sub);
      assert.strictEqual(id, `bb-${sub.replace(/_/g, "-")}`);
      const rel = `adapters/${dir}/${id}/SKILL.md`;
      assert.deepStrictEqual(fs.readdirSync(path.join(DIST, path.dirname(rel))), ["SKILL.md"]);
      const text = read(rel);
      const fm = frontmatter(text, rel);
      assert.deepStrictEqual(Object.keys(fm), ["name", "description"], rel);
      assert.strictEqual(quoted(fm.name, rel), `bb ${sub}`, `${rel}: the name is what the ${agent} list shows and types`);
      assert.ok(quoted(fm.description, rel).startsWith(`Brewboard \`${main} ${sub}\`: ${what}.`), rel);
      assert.ok(text.includes(`Subcommand and arguments: ${sub} (the text the user wrote after \`${main} ${sub}\`, possibly nothing)`), rel);
      assert.doesNotMatch(text, /\$ARGUMENTS/, `${rel}: skills get no $ARGUMENTS substitution`);
      thin(text, sub, rel);
    }
  });
}

test("init's entries keep the sign-in guard in every agent", () => {
  for (const rel of ["adapters/claude-skills/bb init/SKILL.md", "adapters/opencode/bb init.md",
                     "adapters/antigravity-skills/bb-init/SKILL.md", "adapters/codex/bb-init/SKILL.md"]) {
    assert.ok(read(rel).includes("`bb.py init --login --launch --format table`"), rel);
    assert.ok(read(rel).includes("Never run `bb.py init --login` or `bb.py init` yourself"), rel);
  }
});

test("no maintained file still tells anyone to use a /bb-*, /bb:* or /bb/* command", () => {
  const files = [...walk(DIST).filter((f) => /\.(md|py|json)$/.test(f)), ...walk(path.join(ROOT, "lib")),
                 path.join(ROOT, "bin", "brewboard-skill.js"), path.join(ROOT, "README.md")];
  const stale = [];
  for (const f of files) {
    fs.readFileSync(f, "utf8").split("\n").forEach((line, i) => {
      // A /bb-<name>, /bb:<name> or /bb/<name> invocation (not a path such as ~/.codex/skills/bb-find).
      const historical = /historical/.test(line);
      if (!historical && /(^|[\s`"'(])(\/bb[-:/][a-z]|\$bb-[a-z])/.test(line)) stale.push(`${path.relative(ROOT, f)}:${i + 1}: ${line.trim().slice(0, 100)}`);
    });
  }
  assert.deepStrictEqual(stale, []);
});

test("the installer's help lists the new entry points and paths", () => {
  const r = spawnSync(process.execPath, [BIN, "--help"], { encoding: "utf8" });
  assert.strictEqual(r.status, 0);
  assert.match(r.stdout, /~\/\.claude\/commands\/bb\.md +Claude Code: +\/bb \[subcommand\]/);
  assert.match(r.stdout, /~\/\.config\/opencode\/commands\/bb\.md +OpenCode: +\/bb \[subcommand\]/);
  assert.match(r.stdout, /~\/\.gemini\/antigravity-cli\/skills\/bb\/ +Antigravity: +\/bb \[subcommand\]/);
  assert.match(r.stdout, /~\/\.claude\/skills\/bb <subcommand>\/ +Claude Code: +suggestions \/bb list_tasks/);
  assert.match(r.stdout, /~\/\.config\/opencode\/commands\/bb \*\.md +OpenCode: +suggestions \/bb list_tasks/);
  assert.match(r.stdout, /~\/\.gemini\/antigravity-cli\/skills\/bb-\*\/ +Antigravity: +suggestions \/bb list_tasks/);
  assert.match(r.stdout, /~\/\.codex\/skills\/bb-\*\/SKILL\.md +Codex: +picker entries bb list_tasks/);
  assert.doesNotMatch(r.stdout, /\/bb:|\/bb\/<|plugins/, "no namespaced entries");
  assert.doesNotMatch(r.stdout, /(^|\s)\/bb-|bb\*\.md|\.gemini\/config/m);
});

test("installer output on an upgrade: an edited retired command is kept and named, and the install still succeeds", async () => {
  const h = tmpHome();
  try {
    const ap = agentPaths(h.env, h.home);
    fs.mkdirSync(ap.claudeDir, { recursive: true });
    install(h.paths, { agents: detectAgents({ env: h.env, home: h.home, whichFn: () => null }).filter((a) => a.present) });
    const old = path.join(ap.claudeDir, "commands", "bb-find.md");
    const t = tracking.readTracking(h.paths);
    t.files[old] = { sha256: tracking.sha(Buffer.from("old Brewboard command")), agents: ["claude"], mode: "644", created: true, original: null };
    tracking.writeTracking(h.paths, t);
    fs.writeFileSync(old, "old Brewboard command, edited by me");
    const r = await new Promise((resolve) => {
      const c = spawn(process.execPath, [BIN, "--no-login"], { env: { ...h.env, BB_TERMINAL: "none" } });
      let stdout = "", stderr = "";
      c.stdout.on("data", (d) => (stdout += d));
      c.stderr.on("data", (d) => (stderr += d));
      c.on("close", (status) => resolve({ status, stdout, stderr }));
      c.stdin.end("");
    });
    assert.strictEqual(r.status, 0, r.stderr);
    assert.doesNotMatch(r.stderr, /do not match the package/);
    assert.match(r.stdout, /Kept 1 file you changed that this version no longer installs/);
    assert.ok(r.stdout.includes(old));
    assert.match(r.stdout, /INSTALLATION COMPLETE/);
    assert.strictEqual(fs.readFileSync(old, "utf8"), "old Brewboard command, edited by me");
  } finally { h.cleanup(); }
});
